export function workerOrigin(value){const u=new URL(value);if(u.protocol!=='https:'||!u.hostname.endsWith('.workers.dev')||u.username||u.password||u.search||u.hash||(u.pathname!=='/'&&u.pathname!==''))throw Error('Use the public HTTPS workers.dev origin, without a key or path.');return u.origin}
export async function checkConnection(value,fetcher=fetch){if(!value)return {state:'missing',message:'Gemini is not connected. The owner must deploy the Worker, save a fresh key privately as GEMINI_API_KEY, and configure its public URL.'};const origin=workerOrigin(value);const response=await fetcher(origin+'/status',{method:'GET',signal:AbortSignal.timeout(8000)});const body=await response.json();if(!response.ok)throw Error(body.error||'The Worker rejected this website origin. Check ALLOWED_ORIGINS.');if(body.configured!==true)return {state:'setup',message:'Worker reached, but AI is disabled or its secret, model, or usage bindings are missing. Local Analysis remains available.'};return {state:'ready',message:`Worker configured (${typeof body.model==='string'?body.model:'Gemini'}). Google key/model access is not verified until a real question succeeds.`,model:body.model}}
